-- Flyway runs this version once, in a PostgreSQL transaction.
-- Re-running Flyway migrate validates history and skips this applied version.
-- Do not edit an applied migration or execute fragments manually.
SET LOCAL lock_timeout = '3s';

CREATE TABLE pengguna (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nama VARCHAR(150) NOT NULL CHECK (btrim(nama) <> ''),
    email VARCHAR(254) NOT NULL CHECK (email = btrim(email) AND email <> ''),
    password_hash VARCHAR(255) NOT NULL CHECK (btrim(password_hash) <> ''),
    role VARCHAR(20) NOT NULL CHECK (role IN ('SISWA', 'MENTOR')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE UNIQUE INDEX uq_pengguna_email ON pengguna (lower(email));

CREATE TABLE kode_undangan (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    kode VARCHAR(100) NOT NULL UNIQUE CHECK (btrim(kode) <> ''),
    dibuat_oleh BIGINT NOT NULL REFERENCES pengguna(id),
    status VARCHAR(20) NOT NULL DEFAULT 'AKTIF'
        CHECK (status IN ('AKTIF', 'DIGUNAKAN', 'DICABUT')),
    expired_at TIMESTAMPTZ NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT ck_undangan_expiry CHECK (expired_at > created_at)
);
CREATE INDEX idx_kode_undangan_dibuat_oleh ON kode_undangan(dibuat_oleh);

CREATE TABLE materi (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    judul VARCHAR(255) NOT NULL CHECK (btrim(judul) <> ''),
    file_path TEXT NOT NULL CHECK (btrim(file_path) <> ''),
    diunggah_oleh BIGINT NOT NULL REFERENCES pengguna(id),
    jenjang VARCHAR(3) NOT NULL CHECK (jenjang IN ('SD', 'SMP')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX idx_materi_diunggah_oleh ON materi(diunggah_oleh);

CREATE TABLE bagian_materi (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    materi_id BIGINT NOT NULL REFERENCES materi(id),
    judul_bagian VARCHAR(255) NOT NULL CHECK (btrim(judul_bagian) <> ''),
    teks_asli TEXT NOT NULL DEFAULT '',
    teks_ringkasan TEXT,
    urutan INTEGER NOT NULL CHECK (urutan > 0),
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uq_bagian_urutan UNIQUE (materi_id, urutan),
    CONSTRAINT uq_bagian_materi_id UNIQUE (materi_id, id)
);
-- Both unique indexes begin with materi_id and also cover its FK lookup.

CREATE TABLE gambar_materi (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    materi_id BIGINT NOT NULL REFERENCES materi(id),
    bagian_materi_id BIGINT,
    file_path TEXT NOT NULL CHECK (btrim(file_path) <> ''),
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_gambar_bagian FOREIGN KEY (materi_id, bagian_materi_id)
        REFERENCES bagian_materi(materi_id, id)
);
CREATE INDEX idx_gambar_materi_bagian ON gambar_materi(materi_id, bagian_materi_id);
CREATE INDEX idx_gambar_bagian_materi_id ON gambar_materi(bagian_materi_id);

CREATE TABLE soal (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    bagian_materi_id BIGINT NOT NULL REFERENCES bagian_materi(id),
    tipe VARCHAR(30) NOT NULL DEFAULT 'PILIHAN_GANDA' CHECK (tipe = 'PILIHAN_GANDA'),
    pertanyaan TEXT NOT NULL CHECK (btrim(pertanyaan) <> ''),
    gambar_id BIGINT REFERENCES gambar_materi(id),
    status_review VARCHAR(20) NOT NULL DEFAULT 'MENUNGGU'
        CHECK (status_review IN ('MENUNGGU', 'DISETUJUI', 'DITOLAK')),
    direview_oleh BIGINT REFERENCES pengguna(id),
    direview_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT ck_soal_review CHECK (
        (status_review = 'MENUNGGU' AND direview_oleh IS NULL AND direview_at IS NULL)
        OR (status_review IN ('DISETUJUI', 'DITOLAK') AND direview_oleh IS NOT NULL AND direview_at IS NOT NULL)
    )
);
CREATE INDEX idx_soal_bagian_materi_id ON soal(bagian_materi_id);
CREATE INDEX idx_soal_gambar_id ON soal(gambar_id);
CREATE INDEX idx_soal_direview_oleh ON soal(direview_oleh);
CREATE INDEX idx_soal_status_created ON soal(status_review, created_at);

CREATE TABLE opsi_jawaban (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    soal_id BIGINT NOT NULL REFERENCES soal(id),
    teks_opsi TEXT NOT NULL CHECK (btrim(teks_opsi) <> ''),
    urutan SMALLINT NOT NULL CHECK (urutan BETWEEN 1 AND 4),
    is_benar BOOLEAN NOT NULL DEFAULT FALSE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uq_opsi_urutan UNIQUE (soal_id, urutan),
    CONSTRAINT uq_opsi_soal_id UNIQUE (soal_id, id)
);
CREATE UNIQUE INDEX uq_opsi_satu_kunci ON opsi_jawaban(soal_id) WHERE is_benar;

CREATE TABLE sesi_latihan (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    siswa_id BIGINT NOT NULL REFERENCES pengguna(id),
    mode VARCHAR(30) NOT NULL CHECK (mode IN ('ACAK', 'BERWAKTU', 'FOKUS_KELEMAHAN')),
    mulai_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    selesai_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT ck_sesi_waktu CHECK (selesai_at IS NULL OR selesai_at >= mulai_at)
);
CREATE INDEX idx_sesi_latihan_siswa_mulai ON sesi_latihan(siswa_id, mulai_at);

CREATE TABLE riwayat_jawaban (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sesi_id BIGINT NOT NULL REFERENCES sesi_latihan(id),
    soal_id BIGINT NOT NULL REFERENCES soal(id),
    opsi_dipilih BIGINT NOT NULL,
    is_benar BOOLEAN NOT NULL,
    dijawab_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uq_riwayat_sesi_soal UNIQUE (sesi_id, soal_id),
    CONSTRAINT fk_riwayat_opsi_soal FOREIGN KEY (soal_id, opsi_dipilih)
        REFERENCES opsi_jawaban(soal_id, id)
);
CREATE INDEX idx_riwayat_soal_opsi ON riwayat_jawaban(soal_id, opsi_dipilih);
CREATE INDEX idx_riwayat_opsi_dipilih ON riwayat_jawaban(opsi_dipilih);
